export const SERVICES: ServicePageContent[] = [
  {
    ...BASE,
    slug: "sip-pri-trunking",
    badge: "Services",
    title: "SIP & PRI Trunking",
    metaTitle: "SIP & PRI Trunking for Canadian Business | IPfinity",
    headline: "SIP & PRI Trunking for Canadian Business",
    description: "SIP and PRI trunking from an accredited Canadian carrier serving Canada and the US. One company owns the lines, the endpoints and the cloud platform.",
    heroImage: { src: "/images/Nav-grid-web-3-blue-cloudvoice.jpg", alt: "IPfinity CloudVoice trunking connects a business phone system to the carrier network" },
    heroSubhead: "Connect your phone system to our network over SIP or PRI and pay for the number of calls you actually carry at once, not for a line on every desk. A SIP trunk is $30 CAD, fax is included, and we review your channel count every quarter.",
    introHeading: "What SIP and PRI Trunking Do",
    intro: ["A trunk is the connection between your phone system and the public telephone network. SIP trunking carries those calls as data over an IP connection, so channels can be added or removed without anyone visiting the building. PRI trunking uses a dedicated digital circuit, delivering a fixed set of simultaneous channels that does not share capacity with the rest of your internet traffic. Both support direct inward dialling, caller ID, hunt groups and call forwarding, and both connect to a modern IP phone system or to an older PBX through a gateway.","IPfinity has been an accredited telecommunications carrier since 2002. We own the lines, the phones, the features and the cloud queuing end to end, which means there is no third party between you and the network when something needs changing or explaining. Because the calls run across our own switch, we hold the call detail records and the queue statistics ourselves rather than asking another carrier for them.","The practical difference that shows up on the invoice is how the service is scoped. Rather than counting desks, we count simultaneous channels, users, DID numbers, cloud IVR and the redundancy you want behind it. A business with fifty staff rarely has fifty calls up at once, so it rarely needs fifty channels. We right-size that count every quarter and we will tell you to drop channels you are not using."],
    signsHeading: "Signs Your Business Has Outgrown Its Current Lines",
    signsList: ["A stack of individual business lines, each billed separately, with no single view of usage","Callers hear a busy tone at peak times because every channel is already in use","You are opening a branch, or supporting staff who work from home part of the week","An ageing PBX that is expensive to maintain and hard to find parts or engineers for","No failover path if the building loses power, internet or access","Voice quality drops when the office network is busy, because voice and data share the same unmanaged connection","Long distance and international charges that nobody has reviewed in years"],
    bullets: ["A scoping conversation that establishes how many calls you carry at once, not how many desks you have","Channel sizing based on your real call pattern rather than a headcount","Nightingale, our own plug-and-play appliance, installed behind the modem to give voice priority on your connection","Certified handsets from Snom, Grandstream and Yealink, shipped pre-programmed","Number porting managed by us, with the cutover date confirmed in writing before anything moves","A quarterly review of channel usage, including telling you when you can drop capacity"],
    approachHeading: "How We Scope and Deliver Trunks",
    approach: [{"title":"Scoping and Channel Sizing","body":"We start by looking at how your business actually uses the phone: how many calls run at once at your busiest hour, where they come from, how many direct numbers you need and what has to keep working if a site goes dark. That produces a channel count and a number plan instead of a per-seat quote.","iconPath":ICON_CLIPBOARD},{"title":"Build and Install","body":"We configure the trunks on our own network, set up the routing, IVR and queues, and ship the certified handsets pre-programmed. Nightingale goes in behind your modem so voice traffic has priority over everything else sharing the connection. We agree the install window with you and confirm the porting date before any numbers move.","iconPath":ICON_WRENCH},{"title":"Quarterly Right-Sizing","body":"After you are live we keep looking at the usage. Because the calls cross our own network we hold the call detail records, so the review is based on what actually happened rather than an estimate. If you are carrying channels you do not use, we will say so and take them off the bill.","iconPath":ICON_CHART}],
    benefits: [{"title":"Priced by Channel, Not by Desk","body":"A SIP trunk is $30 CAD. You buy the number of simultaneous calls your business really carries, plus the DID numbers your people need, rather than a line for every chair in the building."},{"title":"One Carrier End to End","body":"We are an accredited carrier and we own the lines, the endpoints, the features and the cloud queuing. When something needs changing there is no handoff to a wholesaler and no waiting on another company's ticket queue."},{"title":"Voice Priority on the Line You Already Have","body":"Most businesses do not separate their voice and data networks. Nightingale sits behind the modem and enforces quality of service for voice, so a large upload does not turn into a broken call."},{"title":"Fax Included","body":"Cloud fax comes with the service rather than as a line item, so the one machine that kept an analogue line alive is no longer a reason to keep paying for it."},{"title":"Keep Your Numbers","body":"Number portability lets you bring your existing numbers with you. We handle the paperwork with the losing carrier and confirm the cutover date with you before it happens."},{"title":"Redundancy and Failover","body":"Because your numbers terminate on our network rather than on a box in your building, calls can be rerouted to another site, to mobiles or to a cloud queue without anyone touching your hardware."}],
    timelineHeading: "What the Process Looks Like",
    timeline: [{"title":"Scoping Call","body":"We go through what you have now: the phone system, how many lines, how many numbers, which sites, what has to survive an outage and what you actually spend. If you have recent invoices they answer most of the questions quickly. The output is a channel count, a number plan and a list of anything analogue that has to be handled separately."},{"title":"Design and Quote","body":"We put the design in writing, including trunks and channel count, DID numbers, IVR and queue structure, the endpoints we would certify for your desks, and what redundancy sits behind it. Trunks are quoted at $30 CAD each, with the rest scoped from the design. If a hybrid arrangement makes more sense than a full cutover, we will say so."},{"title":"Install Window","body":"We agree a window with you, usually outside your busiest hours. Handsets arrive pre-programmed, Nightingale goes in behind the modem, and the trunks are brought up and tested before any live traffic moves. Number porting is scheduled separately, because that date is set with the losing carrier and we confirm it before cutover."},{"title":"Right-Sizing Review","body":"Every quarter we look at how many channels you are really using. This is the review where we tell customers to drop capacity, not add it. If your call pattern has changed, the trunk count changes with it, and if you have grown into a second site the number plan gets extended rather than rebuilt."}],
    extraSections: [{"heading":"What Sits on Either End of the Trunk","body":["On your side we certify handsets from Snom, Grandstream and Yealink. Snom is German-built and carries an unusually long three-year warranty, which matters when a phone is going to sit on a desk for a decade. Handsets ship pre-programmed, so the install is a matter of plugging them in rather than configuring each one on site.","Nightingale is our own hardware, a small Raspberry-Pi-class appliance that sits behind your modem and enforces voice priority. We built it because customers almost never segregate their networks, and the most common cause of a call that sounds bad is not the carrier but a saturated shared connection. It arrives pre-programmed alongside the phones.","On the network side we interoperate with the equipment businesses already run. Our technology partners include Cisco, Grandstream, Panasonic, Polycom, AWS, Mitel and IBM, and a working PBX is often a reason to bridge rather than replace. If that is your situation, the hybrid approach keeps the equipment you have already paid for while the trunks move to us."]}],
    faqs: [{"q":"What is the difference between SIP and PRI trunking, and which should we choose?","a":"SIP trunking carries calls over an IP connection. Channels can be added or removed without physical work, it costs less to scale, and it suits businesses with multiple sites or staff who work from home part of the week. PRI trunking uses a dedicated digital circuit and delivers a fixed set of simultaneous channels that do not compete with the rest of your internet traffic, which some businesses still prefer where the connection is poor or where an existing PBX is built around it. The honest answer is that the right choice depends on your connection, your call volume at peak, and what equipment you already own, which is what the scoping call is for. Many sites end up hybrid: SIP where it makes sense, PRI or analogue where something still needs it."},{"q":"How much does a trunk cost?","a":"A SIP trunk is $30 CAD. Beyond that we scope by the number of simultaneous channels you need, users, DID numbers, cloud IVR and the level of redundancy behind it, rather than charging per seat. Fax is included. We would rather quote you after looking at your actual call pattern than publish a package price that turns out to be wrong for your business in either direction."},{"q":"How many channels do we actually need?","a":"Fewer than most people expect. The number you need is not your headcount, it is how many calls your business has running at the same time during its busiest period. A business with fifty staff commonly runs comfortably on a fraction of that in channels. We size it from your real usage, and because the calls cross our own network we can see what that usage is. Every quarter we look again, and if you are carrying channels you are not using we will tell you to drop them."},{"q":"Can we keep our existing phone numbers?","a":"Yes. Number portability lets you keep your numbers when you change carrier. We prepare and submit the paperwork to your current provider and manage the process through to cutover. The timeline is set with the losing carrier rather than by us, so we confirm the date with you in writing before anything moves, and your existing service keeps running until then."},{"q":"What happens to our phones if the internet connection goes down?","a":"Your numbers terminate on our network, not on equipment in your building, so a failure at your site does not take the number offline. Calls can be rerouted to mobiles, to another branch or into a cloud queue, and that is a change in our network rather than work at your premises. Nightingale also helps with the more common problem, which is not a dead connection but a congested one: it gives voice traffic priority behind your modem so calls stay clear while the rest of the office is using the line. Where a site genuinely cannot tolerate any interruption, we design the redundancy into the build rather than leaving it to chance."}],
    relatedLinks: [{"href":"/compare/sip-trunking-vs-pri-trunking","label":"SIP Trunking vs PRI Trunking","eyebrow":"Compare","body":"A side by side look at the two technologies, what each costs to scale, and where each one still makes sense."},{"href":"/services/hybrid-solutions","label":"Hybrid Solutions","eyebrow":"Related","body":"Keep the PBX and handsets you have already paid for while the trunks and the numbers move to our network."},{"href":"/services/disaster-recovery","label":"Disaster Recovery","eyebrow":"Related","body":"Failover routing that keeps your numbers answering when a site loses power, internet or access."}],
    ctaHeading: "Let Us Scope Your Lines",
    ctaBody: "Tell us how many calls you carry at once, what is on your desks today and what you are paying now. We will come back with a channel count, a number plan and a quote.",
  },
  {
    ...BASE,
    slug: "global-did-numbers",
    badge: "Services",
    title: "Global DID Numbers",
    metaTitle: "Global DID Numbers and Global Reach | IPfinity",
    headline: "Global DID Numbers and Global Reach",
    description: "Local and toll-free direct inward dial numbers across Canada, the US and selected international markets, routed onto your IPfinity trunks and answered wherever your team sits.",
    heroImage: { src: "/images/global-reach-icon.jpg", alt: "IPfinity Global Reach, direct inward dial numbers routed across international markets" },
    heroSubhead: "Give a customer in another city or another country a number that is local to them, and answer it on the phones you already have. We route DID numbers across Canada and the United States, and in markets including Colombia, Mexico, parts of Europe, Australia and New Zealand.",
    introHeading: "What a Global DID Number Does",
    intro: ["A direct inward dial number, or DID, is a telephone number that routes to a destination you choose rather than to a physical line. It can ring a single handset, a hunt group, a queue, an IVR menu or a mobile, and where it rings can change without the number changing. That separation between the number and the equipment is what makes it possible to hold a number in one country and answer it in another.","For a business, the practical use is presence. A customer in another market dials a number that looks local to them and pays what a local call costs them, and the call arrives on your trunks alongside everything else. It also works in the other direction: a growing business can hold numbers in a city before it has an office there, and a business that has closed an office can keep the number that its customers have had for years.","IPfinity is an accredited carrier and the numbers route across our own network, which means the DID, the trunk it lands on, the queue it feeds and the record of the call are all in one place. Availability and the rules around each number are set country by country. Some markets require documentation, such as evidence of a local presence, before a number can be issued, and outbound caller ID presentation is governed by local rules too. We confirm what is available and what is required for a market before you commit to it."],
    signsHeading: "When Global Reach Numbers Make Sense",
    signsList: ["Customers or suppliers in another country who currently pay international rates to reach you","Opening in a new city or market before there is an office or a switchboard there","A toll-free number that needs to route somewhere sensible depending on the time of day","Distributed teams who should answer as the business rather than from a personal mobile","A merger or acquisition that leaves the business holding numbers in several places","Individual direct numbers for staff without a separate line for each person","An old number your customers still dial that has to keep working after a move"],
    bullets: ["Local and toll-free numbers in the markets we serve, provisioned and routed by us","Each number pointed at a handset, hunt group, queue, IVR menu or mobile, changeable later","Time of day and time zone routing so an overseas number rings somewhere that is awake","The same trunks, the same phones and one bill, rather than a separate provider per country","Country by country confirmation of availability, documentation and caller ID rules before you commit","Numbers stay portable, so they remain yours if your arrangements change"],
    approachHeading: "How We Set Up Global Reach",
    approach: [{"title":"Market and Number Plan","body":"We start with where your calls come from and where they should land. That gives a list of markets, how many numbers each one needs, and whether local, national or toll-free is the right form for each. We confirm availability and any local documentation requirement for each market before anything is ordered.","iconPath":ICON_CLIPBOARD},{"title":"Provision and Route","body":"We provision the numbers and point them at the destinations you want: a queue, an IVR, a hunt group, a specific handset or a mobile. Routing can follow the clock, so a number in another time zone rings the part of your business that is open, and it can be changed afterwards without touching the number itself.","iconPath":ICON_ROUTING},{"title":"Review and Extend","body":"Numbers accumulate. As part of the same quarterly review we run on channels, we look at which DIDs are actually taking calls, and we will tell you when a number is no longer earning its place. When you open a market, the plan gets extended rather than rebuilt.","iconPath":ICON_CHART}],
    benefits: [{"title":"Local Presence Without an Office","body":"Hold a number that is local to your customers in the markets we serve without leasing space, installing lines or hiring in that country first."},{"title":"One Carrier, One Bill","body":"The numbers, the trunks they land on, the queues they feed and the call records all sit with the same accredited carrier rather than with a different provider in each country."},{"title":"Routing You Can Change","body":"Where a number rings is a setting, not a wiring job. Point it at a queue today and a different branch tomorrow, or have it follow the clock so it always lands somewhere that is open."},{"title":"Direct Numbers Without Direct Lines","body":"Give people and departments their own published numbers without buying a line for each one. Direct inward dialling separates the number from the physical connection."},{"title":"Numbers That Survive Change","body":"Offices move, teams merge and sites close. A number that terminates on our network rather than in a building keeps working through all of that."},{"title":"Scoped to What You Use","body":"DID numbers are part of the same scoping conversation as channels and trunks, so the count is set by what your business needs and reviewed rather than left to grow quietly."}],
    timelineHeading: "What the Process Looks Like",
    timeline: [{"title":"Scoping the Markets","body":"We look at where your inbound calls come from, where you want to be reachable, and what should happen to each number once it rings. This is also where we separate the numbers that need to be local from the ones that would be better as toll-free, and identify anything you already hold that should be ported rather than replaced."},{"title":"Availability and Requirements","body":"Number availability, documentation and caller ID rules differ by country. We check each market you have asked for, tell you what is available and what the local requirement is, and flag any market where the answer is no or where the conditions would not suit you. Lead times vary by country, so we confirm them before you build any plans around a date."},{"title":"Provisioning and Routing","body":"We provision the numbers and build the routing: which queue, IVR, group or handset each one feeds, and what happens outside business hours. We test each number end to end before you publish it anywhere, and where a number is being ported rather than newly issued, the cutover date is confirmed with the losing carrier first."},{"title":"Ongoing Review","body":"The numbers are reviewed alongside your trunks and channels. Because the calls cross our own network, the review is based on the real call records: which numbers take traffic, which markets are producing calls, and whether the routing still matches how your business is staffed. Adding a market later extends the plan rather than starting it again."}],
    extraSections: [{"heading":"Where We Reach","body":["Our core coverage is Canada and the United States, where we operate as an accredited carrier. Beyond that we serve customers with numbers and traffic in Colombia and Mexico, in parts of Europe, and in Australia and New Zealand.","Coverage is not uniform and we would rather tell you that plainly than publish a country count. Whether a particular city or number type is available, what documentation a regulator requires, and what you are permitted to present as outbound caller ID are all decided market by market. Tell us the markets that matter to your business and we will confirm each one before you commit."]},{"heading":"What Happens After the Call Arrives","body":["A DID is only the front door. Once the call is on our network it can go into a cloud queue with announcements, through an IVR menu, to a hunt group, to a single handset or out to a mobile, and it can follow the time of day so a number in another time zone rings a part of your business that is open.","Because we own the platform end to end, the call detail records and the queue statistics for those numbers are ours rather than a third party's. That is what makes it possible to answer questions like which market is actually generating calls, at what hour, and how long those callers waited, without asking another carrier for a report."]}],
    faqs: [{"q":"What is a DID number, in plain terms?","a":"It is a telephone number that is not tied to a physical line. Instead of the number belonging to a socket in a building, it belongs to your account on our network and you decide where it rings: a handset, a group, a queue, an IVR menu or a mobile. That is why one business can hold numbers in several cities or countries while answering them all in one place, and why moving office does not mean changing the number."},{"q":"Which countries can you provide numbers in?","a":"Our core coverage is Canada and the United States. We also serve customers in Colombia and Mexico, in parts of Europe, and in Australia and New Zealand. Availability within a country varies by city and by number type, and some markets require documentation before a number can be issued. We check the specific markets you ask about and tell you what is available before you commit to anything, rather than quoting a country count that would not tell you what you need to know."},{"q":"How long does it take to get a number working?","a":"It depends on the market. Numbers in some countries are issued quickly, while regulated markets require documentation to be submitted and approved first, and that sets the pace rather than we do. Porting an existing number is a separate process again, because the date is agreed with the carrier you are leaving. We confirm the expected timeline for each market at the point you ask for it, so you are not building a launch date on a guess."},{"q":"Can our staff make outbound calls showing the local number?","a":"Often, but not always, and that is worth checking before you plan around it. What a business is permitted to present as outbound caller ID is set by the rules of the country the number belongs to, and those rules differ. We will tell you what is permitted for the specific markets you are using. Where presenting the local number is not allowed, there are usually sensible alternatives, such as presenting a number the recipient can call back on."},{"q":"If we leave, do we keep the numbers?","a":"Numbers are portable. The same portability that lets you bring numbers to us lets you take them elsewhere, subject to the rules of the country the number belongs to. We would rather earn the renewal than hold your numbers hostage, which is also why we tell customers when they are paying for numbers and channels they no longer use."}],
    relatedLinks: [{"href":"/compare/toll-free-vs-local-numbers","label":"Toll-Free vs Local Numbers","eyebrow":"Compare","body":"When a toll-free number is worth it, when a local number does more for you, and how businesses use both."},{"href":"/services/sip-pri-trunking","label":"SIP & PRI Trunking","eyebrow":"Related","body":"The trunks your numbers land on, scoped by simultaneous channels rather than by desk."},{"href":"/services/business-messaging","label":"Business Messaging","eyebrow":"Related","body":"SMS, XMPP messaging and cloud fax on the same account as your voice service."}],
    ctaHeading: "Tell Us Which Markets You Need",
    ctaBody: "Send us the cities or countries where your customers are and how you want those calls answered. We will confirm what is available in each market and what it takes to get there.",
  },
  {
    ...BASE,
    slug: "custom-voice-applications",
    badge: "Services",
    title: "Custom Voice Applications",
    metaTitle: "Custom Voice Applications | IPfinity",
    headline: "Custom Voice Applications Built on Our Own Network",
    description: "IVR menus, call routing, cloud queuing, voicemail to email and smartphone integration, built to match the way your business actually answers the phone.",
    heroImage: { src: "/images/Nav-grid-web-9-image-tech-guy.jpg", alt: "IPfinity engineer building a custom voice application on the CloudVoice platform" },
    heroSubhead: "Most phone systems make you work the way the vendor imagined. Because we are an accredited carrier and own the platform end to end, we can change how a call behaves at the network level rather than bolting another product on top of it.",
    introHeading: "What We Mean by a Custom Voice Application",
    intro: ["A custom voice application is the logic that sits between a caller dialling your number and a person picking up. It decides what the caller hears, which options they are offered, who rings first, what happens when nobody answers, and what happens at six in the evening or on a public holiday. Most businesses run some version of this already, usually whatever the previous phone system happened to support.","The difference with a carrier-owned platform is where that logic lives. IPfinity owns the lines, the phones, the features and the cloud queuing, so a change to how calls behave is a change on our network rather than a new box in your building or another subscription layered on top. It also means the call detail records and the queue statistics belong to us rather than to a wholesaler, which is what makes it possible to answer questions about your own call flow.","In practice this covers auto attendants and IVR menus, time of day and holiday routing, hunt groups and cloud queues with announcements, voicemail delivered to email, overflow to mobiles, smartphone apps so staff away from their desk still present as the business, and routing that spans several sites. Where a business has a genuinely unusual requirement, that is the interesting part of the job rather than an exception we cannot handle."],
    signsHeading: "What We Build",
    signsList: ["Auto attendants and IVR menus, including multi-level menus and direct extension dialling","Time of day, day of week and holiday routing so after-hours calls go somewhere sensible","Hunt groups and cloud call queues with position announcements and overflow rules","Voicemail delivered to email so messages reach people who are not at a desk","Smartphone integration, so staff away from the office still make and take calls as the business","Routing that spans several sites, sending a call to whichever branch can answer it","Call centre flows with queue reporting drawn from our own call records","Integrations with the systems your team already works in, where an interface exists"],
    bullets: ["A working session where we map how calls move through your business today, including the parts that are not written down","A call flow you can read and approve before anything is built","Configuration on our own platform, so there is no extra hardware in your building to buy or maintain","Testing against the real numbers and the real handsets before the flow goes live","Adjustments after go-live, once you have heard how it behaves with real callers","Queue and call reporting from our own records rather than a third party's summary"],
    approachHeading: "How We Build a Voice Application",
    approach: [{"title":"Map the Call Flow","body":"We work through what actually happens to a call today: who answers first, what the receptionist does with it, where it goes when nobody picks up, and what happens out of hours. Most of this lives in people's heads rather than in a document, so the mapping session usually surfaces the real requirement faster than a specification would.","iconPath":ICON_CLIPBOARD},{"title":"Build and Test","body":"We build the flow on our own platform and test it against your real numbers and handsets before it carries live traffic. You hear the menus, the announcements and the hold experience as a caller would, and we change the wording, the order and the timings while it is still easy to change them.","iconPath":ICON_CODE},{"title":"Tune After Go-Live","body":"Real callers behave differently from a test plan. Once the flow is live we look at what the call records show, which options people choose, where they drop out and how long they wait, and we adjust. Changes are made on our network, so they do not require a visit or new equipment.","iconPath":ICON_COG}],
    benefits: [{"title":"Built on the Network, Not Bolted On","body":"We own the switch, the trunks, the endpoints and the queuing, so the call flow is configured at the carrier level instead of assembled from separate products that each have to be paid for and kept in step."},{"title":"Changes Without New Hardware","body":"Adjusting a menu, a schedule or an overflow rule is a configuration change on our platform. There is no server in a cupboard that has to be upgraded before your opening hours can change."},{"title":"Your Own Call Data","body":"Because the calls cross our network cradle to grave, the call detail records and queue statistics are ours to give you rather than something we have to request from a wholesaler."},{"title":"Works With Your Desks and Your Mobiles","body":"The same flow can ring a certified desk phone, a hunt group, a queue and a smartphone app, so staff who are not at their desk still answer as the business."},{"title":"Multi-Site by Design","body":"Routing spans sites rather than being duplicated at each one, so a call can land wherever it can actually be answered instead of ringing out at an empty branch."},{"title":"Scoped Like Everything Else","body":"Voice applications are scoped along with your trunks, channels, DID numbers and cloud IVR rather than sold per seat, so the price follows what the business actually uses."}],
    timelineHeading: "What to Expect",
    timeline: [{"title":"Discovery","body":"We sit down with the people who actually answer the phone as well as the people who own the budget. We map the current call flow, note the parts that annoy staff and callers, and establish what has to stay exactly as it is. Recent call records, if you have them, tell us more in ten minutes than a requirements document does in a week."},{"title":"Design","body":"You get the proposed call flow in a form you can read and mark up: what the caller hears, which options exist, who rings in what order, what happens when nobody answers and what happens out of hours and on holidays. We agree the wording of the announcements here rather than after they have been recorded."},{"title":"Build and Test","body":"We configure the flow on our platform and test it against your real numbers and handsets. You call in and walk through it as a customer would. This is the point at which most of the useful changes get made, because hearing a menu is very different from reading one."},{"title":"Go Live and Tune","body":"We cut the flow over in a window you agree, and then we watch how real callers use it. Which options they pick, where they hang up, how long they wait in queue. Adjustments are configuration changes on our side, so tuning does not mean another project."}],
    extraSections: [{"heading":"Why Owning the Platform Matters Here","body":["A great deal of what is sold as a business phone feature is a layer sitting on somebody else's network. It works until you need it to do something the layer was not designed for, or until a problem has to be traced across two companies who each believe it belongs to the other.","IPfinity has been an accredited telecommunications carrier since 2002 and owns the connection cradle to grave: the lines, the phones, the features and the cloud queuing. When a call does something unexpected, the record of that call is ours. When a flow needs to behave in a way nobody has asked for before, the change happens where the call is actually handled.","That is also why the reporting is worth something. Queue statistics assembled from a third party's summary tell you what that summary chose to include. Statistics drawn from our own call records can answer the question you actually asked."]},{"heading":"What the Application Runs On","body":["On the desk we certify handsets from Snom, Grandstream and Yealink, shipped pre-programmed so an install is a matter of plugging them in. Snom is German-built and carries an unusually long three-year warranty, which is worth knowing when you are buying phones that should last a decade.","Away from the desk, smartphone integration lets staff make and take calls as the business rather than from a personal number, which keeps the call flow intact for people who are rarely in one place.","Behind the modem, Nightingale enforces voice priority on the connection. A carefully built call flow still sounds poor if voice is competing with everything else on an unmanaged link, and very few businesses separate their networks, so we ship the appliance pre-programmed alongside the phones."]}],
    faqs: [{"q":"Can you reproduce the call flow we have now?","a":"Usually, and often it is the right starting point. We map what happens today first, including the informal parts that are not documented anywhere, and reproduce the behaviour your staff and callers already expect. The useful conversation is then about the two or three places where the existing flow is fighting people rather than helping them, which tends to be the after-hours path, the overflow when nobody answers, or a menu with more options than anyone listens to."},{"q":"Do we need new phones?","a":"Not necessarily. We certify handsets from Snom, Grandstream and Yealink and ship them pre-programmed, and for most businesses that is the simplest path. But a working PBX and serviceable handsets are an asset, not a problem, and a hybrid arrangement that bridges what you already own to our network is often the better answer. That is a question for the scoping conversation rather than something to decide in advance."},{"q":"How do we get changes made later?","a":"You ask us. Menus, schedules, holiday routing, hunt group order and overflow rules are configuration on our platform, so a change does not mean a site visit or a hardware upgrade. Businesses change their opening hours, add a department, or discover that an option in the menu is sending calls to the wrong place, and none of that should need a project."},{"q":"Does this work for staff who are not in the office?","a":"Yes. Smartphone integration means someone working from home, on a site visit or between branches can take and make calls as the business rather than from a personal mobile, and the call flow treats them as a destination like any other. That also matters at the other end of the call, because a customer who reaches a person rather than a voicemail box does not need to be called back."},{"q":"What reporting do we get?","a":"Because the calls run across our own network, the call detail records and queue statistics come from us rather than from a third party. That covers the practical questions: how many calls arrived, when the busy periods are, how long callers waited in queue, how many gave up, and which parts of the menu are actually used. The same records are what we use in the quarterly review when we look at whether you are paying for channels you do not need."}],
    relatedLinks: [{"href":"/services/business-messaging","label":"Business Messaging","eyebrow":"Related","body":"SMS, XMPP messaging and cloud fax, on the same account and the same bill as your voice service."},{"href":"/services/sip-pri-trunking","label":"SIP & PRI Trunking","eyebrow":"Related","body":"The trunks and channels underneath the call flow, scoped by simultaneous calls rather than by desk."},{"href":"/technology","label":"Technology and Certified Endpoints","eyebrow":"Related","body":"Nightingale, the handsets we certify, and the technology partners our platform interoperates with."}],
    ctaHeading: "Tell Us How Your Calls Should Behave",
    ctaBody: "Describe what happens to a call today and what you wish happened instead. We will map the flow with you and scope what it takes to build it.",
  },
  {
    ...BASE,
    slug: "business-messaging",
    badge: "Services",
    title: "Business Messaging",
    metaTitle: "Business SMS, XMPP Messaging and Cloud Fax | IPfinity",
    headline: "Business Messaging, SMS, XMPP and Cloud Fax",
    description: "Send and receive business SMS, run XMPP messaging for your team, and keep fax working without a fax machine, all on the same IPfinity account as your voice service.",
    heroImage: { src: "/images/Nav-grid-web-11-image-hand.jpg", alt: "Business messaging from a mobile device on the IPfinity network" },
    heroSubhead: "Customers text. Suppliers still fax. Teams chat. Running each of those through a different provider means three bills, three support paths and no single record of what your business sent. We carry messaging on the same network as your voice, and fax is included.",
    introHeading: "What Business Messaging Covers",
    intro: ["Business messaging is the set of written channels that sit alongside your phone service: SMS to and from your business numbers, XMPP messaging between your own people, and fax that arrives as email instead of paper. They are usually treated as three separate problems bought from three separate places, which is why most businesses cannot answer a simple question like what was sent to a customer last Tuesday.","Because IPfinity is an accredited carrier and owns the platform end to end, messaging runs on the same account and the same numbers as your voice service. The number a customer calls is the number they can text. Faxes arrive as email rather than sitting in a tray. Internal chat runs on XMPP, an open standard, rather than on a consumer app that happens to be on everybody's phone.","The most common reason businesses fix this is not the technology but the record. When staff use personal mobiles, the business number never appears, the customer builds a relationship with the individual rather than the company, and the conversation leaves with them. Moving that traffic onto business numbers changes who the customer is dealing with and what the business still has when someone moves on."],
    signsHeading: "Signs Your Messaging Needs Attention",
    signsList: ["Staff sending work messages from personal mobiles, so the business number never appears","An analogue line kept alive solely for a fax machine that receives a handful of pages a month","No record of what was sent to a customer, because it lives on someone else's phone","Service and delivery notifications typed out by hand, one at a time","A different provider and a different bill for voice, SMS and fax","Teams in other countries coordinating on consumer chat apps because nothing better was provided","Customers texting your main business number and nobody seeing it"],
    bullets: ["SMS sent and received on your business numbers rather than on personal mobiles","Cloud fax to and from email, with no machine and no dedicated analogue line","XMPP messaging for internal team communication on an open standard","One account, one carrier and one bill alongside your voice service","Messaging scoped with your trunks, channels and DID numbers rather than sold per seat","Practical help with consent and record keeping before a messaging programme goes out"],
    approachHeading: "How We Set Messaging Up",
    approach: [{"title":"Work Out What Is Actually Being Sent","body":"We look at what your business sends today and how: the texts going out from personal mobiles, the faxes still coming in, the internal chat that has drifted onto consumer apps. That usually identifies one or two channels that matter and several that people assume matter but do not.","iconPath":ICON_CLIPBOARD},{"title":"Enable It on Your Numbers","body":"We enable messaging on the business numbers you already use, set up cloud fax so incoming pages arrive as email, and configure XMPP for internal messaging. Fax is included in the service, so the analogue line that existed for one machine can usually be retired.","iconPath":ICON_ROUTING},{"title":"Review With Everything Else","body":"Messaging is reviewed alongside your trunks, channels and numbers in the quarterly right-sizing. If a messaging number or a fax line is no longer carrying anything, we will tell you, the same way we tell customers when they are carrying channels they do not use.","iconPath":ICON_CHART}],
    benefits: [{"title":"Your Business Number, Not a Personal One","body":"Texts go out from the number your customers already know. The conversation belongs to the business rather than to whoever happened to answer it from their own phone."},{"title":"Fax Without a Fax Machine","body":"Cloud fax is included with the service. Faxes arrive as email and go out the same way, which usually removes the last reason a business is paying for an analogue line."},{"title":"One Carrier for Voice and Messaging","body":"Voice, SMS, fax and internal messaging sit on the same account with the same accredited carrier, so there is one bill and one place to call when something needs fixing."},{"title":"XMPP for Internal Chat","body":"Internal messaging runs on an open standard rather than on a consumer app, which keeps work conversation inside something the business actually controls."},{"title":"A Record That Stays With You","body":"Because the traffic runs on your business numbers across our network, what was sent does not walk out of the door when an employee does."},{"title":"Scoped, Not Per Seat","body":"Messaging is part of the same scoping conversation as trunks, channels, DID numbers and IVR, so it is sized to what your business sends rather than to your headcount."}],
    timelineHeading: "What the Process Looks Like",
    timeline: [{"title":"Scoping","body":"We establish what your business sends and receives in writing today, which numbers should be able to text, who still faxes you, and what your internal teams are using to talk to each other. This is also where we work out which analogue lines exist purely to keep a fax machine alive."},{"title":"Enabling and Testing","body":"We enable messaging on the agreed numbers, set up cloud fax delivery to the right mailboxes and configure XMPP for internal use. Everything is tested end to end before anyone relies on it, including a real fax in and a real fax out, because that is the one people assume will be fine and occasionally is not."},{"title":"Moving the Traffic Over","body":"Staff move from personal mobiles to the business numbers, and inbound faxes start arriving as email. We keep the old path in place until the new one has been proven in normal use rather than cutting it on the same day. Once the fax traffic is landing reliably, the dedicated analogue line can usually be retired."},{"title":"Review","body":"Messaging is looked at in the same quarterly review as your trunks and channels. Numbers that are not carrying anything get flagged, and if your usage has changed, the scope changes with it rather than quietly staying where it was set on day one."}],
    extraSections: [{"heading":"Cloud Fax, and Why It Is Still Here","body":["Fax has outlived several generations of predictions about its demise, because entire industries still run on it. Legal, logistics, finance, government and healthcare all still send documents that way, and a business that cannot receive a fax simply does not receive those documents.","Cloud fax keeps that working without the machine or the line. Incoming faxes arrive as email attachments, outgoing faxes are sent the same way, and the number that people have been faxing for years carries on working. Fax is included in our service rather than billed separately, which is usually what makes it worth doing: the saving is the analogue line that existed for one device in the corner."]},{"heading":"Consent, Records and Privacy","body":["Messaging is not the same as calling from a compliance point of view. Commercial electronic messages sent in Canada are subject to consent rules under CASL, and personal information handled in the course of commercial activity falls under PIPEDA. Those obligations sit with the business sending the messages, not with the carrier, and they are worth getting right before a programme goes out rather than after.","Customers in regulated sectors carry more on top of that. An Ontario health organisation, for example, has obligations under PHIPA for the information it handles, and how it uses a messaging channel needs to reflect that. We are a telecommunications carrier rather than a compliance advisor, so what we can do is be clear about how the service works, what records exist and where they sit, so your own advisors can make the call.","The practical starting point is simpler than it sounds: send from business numbers, keep the record with the business, and know what you sent and when."]}],
    faqs: [{"q":"Can customers text our main business number?","a":"That is the usual arrangement. Messaging is enabled on the business numbers you already publish, so a customer who has your number does not need a second one to text you, and your staff do not need to hand out personal mobiles. Which numbers are enabled is your decision, and it can be one main number, a departmental number or direct numbers for individual people."},{"q":"Do we still need a fax machine or a fax line?","a":"Usually not. Cloud fax sends and receives through email, so the pages arrive in a mailbox instead of a tray, and the number people have always faxed keeps working. For most businesses the dedicated analogue line exists only to serve that one machine, so it can be retired once the fax traffic is landing reliably. We keep both paths running until that is proven rather than switching on the same day."},{"q":"What is XMPP, and how is it different from SMS?","a":"SMS goes out over the mobile network to people outside your business, such as customers and suppliers, and it works on any phone. XMPP is an open messaging standard used for chat between your own people, so it suits internal team communication rather than customer contact. They solve different problems, which is why a business usually wants both: one for reaching the outside world on a number it owns, one for talking internally without that conversation living on a consumer app."},{"q":"Is messaging billed separately from our phone service?","a":"Messaging is scoped as part of the same conversation as your trunks, channels, DID numbers and IVR rather than as a separate product line, and fax is included in the service. We would rather quote it after establishing what your business actually sends than publish a per-message package that turns out to be wrong in either direction."},{"q":"What about consent rules for text messages?","a":"Commercial messages sent in Canada fall under CASL, which sets rules about consent and about identifying the sender, and personal information collected along the way falls under PIPEDA. Those obligations belong to the business sending the messages. We can explain how the service works, which numbers messages come from and what records exist, which is what your own advisors need in order to sign off a programme. What we would not do is tell you that using our service makes the question go away."}],
    relatedLinks: [{"href":"/compare/sms-vs-xmpp-messaging","label":"SMS vs XMPP Messaging","eyebrow":"Compare","body":"Which messaging standard fits which job, and why most businesses end up using both for different purposes."},{"href":"/services/custom-voice-applications","label":"Custom Voice Applications","eyebrow":"Related","body":"IVR menus, cloud queuing and routing built on the same network your messaging runs on."},{"href":"/services/global-did-numbers","label":"Global DID Numbers","eyebrow":"Related","body":"Local and toll-free numbers across the markets we serve, routed to wherever your team answers."}],
    ctaHeading: "Let Us Look at What You Are Sending",
    ctaBody: "Tell us what goes out by text, what still arrives by fax and what your teams use to talk to each other. We will scope messaging alongside your voice service and quote it as one thing.",
  },
  {
    ...BASE,
    slug: "hybrid-solutions",
    badge: "Services",
    title: "Hybrid Solutions",
    metaTitle: "Hybrid Voice Solutions, Legacy PBX and Cloud | IPfinity",
    headline: "Hybrid Solutions for Legacy and Cloud Voice",
    description: "Keep the PBX and handsets you have already paid for and put cloud voice in front of them. IPfinity bridges legacy and all-IP so you can move one site at a time.",
    heroImage: { src: "/images/end-points-icon-copy.jpg", alt: "Certified endpoints and equipment bridging legacy phone systems to the IPfinity cloud" },
    heroSubhead: "A working phone system is an asset, not an obstacle. We connect our trunks and numbers to what you already run, so the parts that still do their job stay where they are and the rest moves to the cloud when it suits your budget rather than ours.",
    introHeading: "What a Hybrid Solution Actually Is",
    intro: ["A hybrid solution runs cloud voice and existing on-premises equipment side by side, with our trunks and numbers connecting the two. The PBX in the cupboard keeps doing what it does. The numbers, the trunks, the queuing and the new sites live on our network. Calls move between them without your staff or your callers having to think about which side of the line they are on.","Businesses end up here for good reasons rather than out of indecision. A PBX bought five years ago may have years of life in it. A site with a poor connection may not be a candidate for all-IP yet. There are almost always analogue devices that nobody mentions until cutover day: an alarm panel, a lift phone, a door entry system, a payment terminal, a fax machine in an office that still receives them. Replacing a whole estate in one weekend to accommodate those is expensive, and it is rarely necessary.","IPfinity has been an accredited carrier since 2002 and owns the lines, the phones, the features and the cloud queuing end to end, so the bridge between old and new is something we operate rather than something we broker. That matters when a call behaves oddly halfway between two systems, because the trunk, the routing and the call record are all ours to look at."],
    signsHeading: "When a Hybrid Approach Is the Right Call",
    signsList: ["A PBX that still works and still has book value, with no appetite to write it off this year","Several sites running different systems after growth or an acquisition","Analogue devices that cannot simply move: alarm panels, lift phones, door entry, payment terminals","A branch where the internet connection is not yet good enough for all-IP voice","Handsets that are serviceable and would cost real money to replace across every desk","A preference for moving one site at a time and learning from the first one","A capital cycle that makes a staged migration far easier to approve than a single large project"],
    bullets: ["An inventory of what you actually have, including the analogue devices nobody lists","A migration order, site by site, with the lowest-risk site first","Our trunks and numbers connected to your existing system so both sides work at once","Nightingale installed behind the modem so voice keeps priority on the shared connection","Certified handsets from Snom, Grandstream and Yealink added where they are needed, not everywhere at once","A retirement plan for the legacy equipment, on your timetable rather than a vendor deadline"],
    approachHeading: "How We Approach a Hybrid Build",
    approach: [{"title":"Inventory What Is There","body":"We find out what you actually have: the phone system, the handsets, the lines, the sites and, most importantly, the analogue devices that are easy to forget. Alarm panels, lift phones and door entry systems have a habit of appearing at cutover, and they are much cheaper to plan for than to discover.","iconPath":ICON_CLIPBOARD},{"title":"Bridge and Run in Parallel","body":"We connect our trunks and numbers to your existing system so both sides carry calls. Staff keep the phones they know while the new arrangement proves itself, and a site that is not ready to move does not have to. Nightingale goes in behind the modem so voice has priority on the connection.","iconPath":ICON_WRENCH},{"title":"Retire Legacy at Your Pace","body":"Once a site is running cleanly on the new path, the old equipment and the lines behind it can be retired. That happens site by site on your timetable. The quarterly right-sizing review then covers the whole estate, so capacity you no longer need comes off the bill.","iconPath":ICON_FAILOVER}],
    benefits: [{"title":"Protect What You Have Paid For","body":"A serviceable PBX and working handsets keep doing their job. Nothing is written off to suit a migration schedule, which is usually what makes the numbers work for a hybrid approach in the first place."},{"title":"Move One Site at a Time","body":"The first site is the one you learn on. Later sites go faster and carry less risk, and a branch that is not ready, because of its connection or its timing, simply waits without holding up the others."},{"title":"One Carrier Across Both Sides","body":"The trunks, the numbers, the routing and the call records sit with us whether a site is legacy or all-IP, so there is no argument about whose network a problem belongs to."},{"title":"Analogue Keeps Working","body":"Alarm panels, lift phones, door entry systems and fax machines are planned for rather than discovered. Where something genuinely has to stay analogue, it stays, and the rest still moves."},{"title":"Voice Priority Where It Is Needed","body":"Nightingale sits behind the modem and enforces quality of service for voice. Businesses rarely separate their networks, and on a shared connection that is usually the difference between a clear call and a poor one."},{"title":"Cut Over When You Are Ready","body":"The end state is still all-IP for most businesses. A hybrid arrangement changes when you get there and how much risk you take on the way, not whether you get there."}],
    timelineHeading: "What to Expect",
    timeline: [{"title":"Inventory and Site Survey","body":"We document what exists: the phone system and its age, how many handsets and of what type, which lines terminate where, how many sites, and every analogue device hanging off the system. Recent invoices are useful here because they show lines that people have forgotten are still being paid for."},{"title":"Migration Order","body":"We propose which site moves first and why, usually the one where the risk is lowest and the lesson is most useful. You get the order in writing along with what changes at each step, what stays as it is, and which analogue devices need a specific answer rather than a general one."},{"title":"Bridge the First Site","body":"Our trunks and numbers are connected to the existing system and run in parallel. Staff keep the handsets they know. Nightingale goes in behind the modem. We test with real calls in a window you agree, and porting, where it applies, is scheduled separately with the date confirmed with the losing carrier."},{"title":"Extend and Retire","body":"Later sites follow the pattern established at the first. As each one settles, the legacy equipment and the lines behind it can be retired on your timetable. The quarterly review then covers the whole estate, including telling you where you are still paying for capacity you no longer use."}],
    extraSections: [{"heading":"What We Connect To","body":["Our technology partners include Cisco, Grandstream, Panasonic, Polycom, AWS, Mitel and IBM, and a hybrid build is usually a matter of connecting to equipment a business already owns rather than replacing it. If your PBX is a make we have not named, that is a question for the survey rather than an automatic no.","Where new handsets are needed, we certify Snom, Grandstream and Yealink and ship them pre-programmed. Snom is German-built with an unusually long three-year warranty. Adding phones at the desks that need them, rather than at every desk, is one of the reasons a staged approach costs less than a full replacement.","Nightingale is our own appliance, a small Raspberry-Pi-class device that sits behind the modem and enforces voice priority on the connection. It matters more in a hybrid build than almost anywhere else, because during migration a site is often carrying voice over a link that was never designed to prioritise it."]},{"heading":"The Devices Everyone Forgets","body":["Alarm panels, lift and elevator phones, door entry systems, gate intercoms, payment terminals and fax machines all tend to sit on analogue lines that nobody has thought about in years. They do not appear on an org chart and they rarely appear in a migration plan, but they will appear on cutover day.","We look for them during the inventory and give each one a specific answer: it moves, it stays analogue, or it gets handled another way. Fax is usually the easiest of these, because cloud fax is included in our service and removes the last reason the line was there. The others are decided case by case, which is exactly why they need to be found early."]}],
    faqs: [{"q":"Do we have to replace our PBX?","a":"No, and quite often you should not. If the system works and still has value, the sensible move is to connect it to our trunks and numbers and leave it in place, then retire it when the business is ready rather than when a migration schedule says so. What changes immediately is the connectivity, the numbers and what you pay for them. What changes later is the equipment, on your timetable."},{"q":"Can one site be on the cloud while another stays legacy?","a":"Yes, and that is the normal shape of a hybrid build. Sites move in the order that makes sense for the business, usually starting with the lowest-risk one, and a branch with a poor connection or an awkward lease can wait without holding everything else up. Because the numbers and routing sit on our network, calls move between the two kinds of site without your staff or your callers noticing which is which."},{"q":"What happens to the alarm panel and the lift phone?","a":"They get a specific answer during the inventory rather than a general one, which is the single biggest difference between a smooth cutover and a bad one. Some devices move, some stay on an analogue line that is kept deliberately, and some are handled another way. The point is to find them before the migration rather than on the morning of it, because these are exactly the services nobody notices until they are needed."},{"q":"How long do we run in hybrid?","a":"As long as it is useful. Some businesses bridge for a few months while sites move in sequence. Others keep a hybrid arrangement for years because a particular site or a particular device genuinely warrants it. We are not going to push a deadline at you, partly because the same quarterly review that governs everything else applies here: we look at what you are actually using and tell you when something can come off the bill."},{"q":"Does a hybrid arrangement mean paying for two systems?","a":"You pay for the connectivity you actually use. A SIP trunk is $30 CAD, and we size channels from your real call pattern rather than from headcount, so a site that is still mostly legacy does not need a full complement of cloud channels sitting idle. The legacy costs that remain are the ones you already have, and the retirement plan exists specifically so they come off as each site settles."}],
    relatedLinks: [{"href":"/compare/hybrid-vs-all-ip-telecommunications","label":"Hybrid vs All-IP","eyebrow":"Compare","body":"What you gain and give up by moving everything at once, compared with bridging and migrating site by site."},{"href":"/compare/cloud-voice-vs-on-premises-pbx","label":"Cloud Voice vs On-Premises PBX","eyebrow":"Compare","body":"Where the costs actually sit in each model, and which questions decide it for a given business."},{"href":"/services/sip-pri-trunking","label":"SIP & PRI Trunking","eyebrow":"Related","body":"The trunks that connect your existing system to our network, scoped by simultaneous channels."}],
    ctaHeading: "Let Us Look at What You Already Run",
    ctaBody: "Tell us what phone system you have, how many sites and what is still analogue. We will propose a migration order and scope the trunks, without asking you to write off equipment that still works.",
  },
  {
    ...BASE,
    slug: "disaster-recovery",
    badge: "Services",
    title: "Disaster Recovery",
    metaTitle: "Voice Disaster Recovery and Failover | IPfinity",
    headline: "Disaster Recovery and Failover for Business Voice",
    description: "When a site loses power, internet or access, your numbers keep ringing. IPfinity reroutes calls because the routing lives on our network rather than in your building.",
    heroImage: { src: "/images/Nav-grid-web-5-purple-nightingale.jpg", alt: "Nightingale, the IPfinity appliance that protects voice quality and supports failover" },
    heroSubhead: "The question is not whether a site will ever go dark. It is what your callers hear when it does. Because your numbers terminate on our network rather than on a box in your office, rerouting them is a routing decision rather than an emergency.",
    introHeading: "What Voice Disaster Recovery Means",
    intro: ["For voice, disaster recovery is the answer to a narrow and practical question: when this building loses power, loses its connection, or cannot be entered, where do the calls go? Everything else follows from that. If the numbers terminate on equipment inside the building, the honest answer is usually nowhere, and callers hear ringing that nobody will ever answer.","When the numbers terminate on a carrier network instead, the answer becomes a choice. Calls can go to mobiles, to another branch, to a cloud queue with an announcement, or to a different menu that tells callers what is happening. None of that requires anyone to reach the affected site, which matters most in precisely the situations where nobody can.","IPfinity is an accredited carrier and owns the lines, the phones, the features and the cloud queuing end to end. The routing, the trunks and the call records are all on our network, so a failover is a change we make rather than a change that depends on your hardware still being reachable. Redundancy and failover are part of how a service is scoped rather than a product bolted on after an incident."],
    signsHeading: "Signs Your Voice Has a Single Point of Failure",
    signsList: ["The phone system lives in a cupboard at one site and everything depends on it","Your main number physically terminates at an office nobody may be able to reach","No written answer to what happens on a storm day or during a building closure","The IVR menu and the call queue run on premises hardware rather than in the cloud","During past outages, staff handed out personal mobile numbers to keep working","A single internet connection carrying every call the business makes","A failover arrangement that exists on paper but has never actually been tested"],
    bullets: ["A clear map of where your calls would stop if a given site went down","Failover destinations agreed in advance: mobiles, another branch, or a cloud queue","Rerouting performed on our network, with no requirement to reach the affected building","Cloud-based IVR and queuing, so the announcement your callers hear is not inside the site that failed","Nightingale behind the modem, because a congested link is a far more common failure than a dead one","A tested plan rather than a documented one, including what happens when you switch back"],
    approachHeading: "How We Build Failover",
    approach: [{"title":"Find the Single Points of Failure","body":"We work through where your calls would actually stop: which site the numbers terminate at, where the IVR and queue run, how many connections carry voice, and what depends on a person being physically present. Most businesses have one or two that matter and several that turn out not to.","iconPath":ICON_CLIPBOARD},{"title":"Build the Failover Path","body":"We agree in advance where calls go when a site is unavailable: mobiles, another branch, or a cloud queue with an announcement that tells callers something true. Because the routing lives on our network, invoking it does not depend on anything at the affected site still working.","iconPath":ICON_FAILOVER},{"title":"Test It, Then Test It Again","body":"A failover plan nobody has run is a document, not a capability. We test the path with real calls, including the switch back, and we revisit it when your sites, staffing or numbers change. This sits alongside the quarterly review we already run on your channels and numbers.","iconPath":ICON_COG}],
    benefits: [{"title":"The Routing Is Not in Your Building","body":"Your numbers terminate on our network. A site losing power, connectivity or access does not take the number with it, because the number was never physically there."},{"title":"Calls Go Somewhere Real","body":"Failover destinations are agreed in advance: mobiles, another branch, or a cloud queue. Callers reach a person or at least an announcement that tells them something true, rather than ringing out."},{"title":"No Truck Roll to Invoke It","body":"Rerouting is a change on our side. Nobody has to drive to the affected site, get past a closed building or find the cupboard the phone system lives in."},{"title":"Your Queue Survives the Site","body":"Cloud queuing and cloud IVR mean the hold experience and the menus are not hosted inside the building that just went dark."},{"title":"Protection From the Common Failure","body":"Total outages are rare. Congested connections are not. Nightingale enforces voice priority behind your modem, which addresses the failure mode businesses actually meet most often."},{"title":"A Plan That Has Been Run","body":"We test the failover path and the switch back with real calls, so you find out what it does before an incident rather than during one."}],
    timelineHeading: "What to Expect",
    timeline: [{"title":"Mapping the Risk","body":"We establish what actually breaks and where. Which site the numbers land at, where the IVR and queues run, how many connections carry voice, which people have to be physically present for calls to be answered, and what your business has already lived through. The output is a short list of the failures that would genuinely hurt, not a generic risk register."},{"title":"Designing the Failover Path","body":"For each scenario we agree the destination in advance: which mobiles, which branch, which queue, and what the announcement says. We also agree who can ask for failover to be invoked and how, because during an incident is the wrong time to be deciding who has the authority to make the call."},{"title":"Building and Testing","body":"We configure the routing on our network and then test it with real calls, including switching back afterwards, which is the step most plans skip. Testing is scheduled at a time that suits you. What we are looking for is the gap between what the plan says and what a caller actually experiences."},{"title":"Keeping It Current","body":"Sites open, close and move, staff change and numbers get added. A failover path that was right two years ago may now point at a branch that no longer exists. We revisit the plan alongside the quarterly review of your channels and numbers, so it stays connected to how the business is actually arranged."}],
    extraSections: [{"heading":"Where the Failover Actually Happens","body":["The reason this works is structural rather than clever. A traditional phone system terminates numbers on equipment inside a building, so the building is a single point of failure for the numbers as well as for the people. A cloud carrier terminates them on its own network, which means the number and the building are separate things that can fail independently.","IPfinity owns that network cradle to grave: the lines, the phones, the features and the cloud queuing. When calls need to go somewhere else, the change is made where the calls are already being handled. There is no third party to raise a ticket with and no dependency on equipment at a site that may be dark, flooded or closed.","This is also why the announcement matters. A caller who reaches a queue that says the office is closed today and offers to take them to someone else has been told something true. A caller who hears endless ringing draws their own conclusions about the business, and they are rarely generous ones."]},{"heading":"The Outage You Are More Likely to Have","body":["Most businesses plan for the dramatic failure and then spend years living with the mundane one. A connection that is not down but is saturated produces calls that break up, drop or sound poor, and it is frequently misdiagnosed as a problem with the phone service.","Nightingale exists because of this. It is our own hardware, a Raspberry-Pi-class appliance that sits behind your modem and enforces quality of service so voice has priority over everything else sharing the link. It ships pre-programmed alongside the phones, because very few customers segregate their voice and data networks and it is unreasonable to expect them to.","Alongside that, the quarterly right-sizing review keeps capacity honest. Knowing how many calls you actually carry at peak is what tells you whether your failover destination could handle them, which is a question worth answering before the day you need it."]}],
    faqs: [{"q":"What happens to our calls if the office loses power?","a":"They go wherever you have agreed in advance. Your numbers terminate on our network rather than on equipment in the building, so losing power at the site does not take the numbers offline. Calls can be rerouted to mobiles, to another branch, or into a cloud queue with an announcement. Because the change happens on our side, nobody needs to reach the building or the phone system to make it happen, which is the whole point in a situation where that is often impossible."},{"q":"Do we need a second internet connection?","a":"Sometimes, but not always, and it is worth being clear about what a second connection buys you. It protects a site that has to keep answering calls on its own handsets. It does nothing extra for a business whose failover plan is to send calls to mobiles or another branch, because those paths do not depend on the failed site at all. We look at what each site genuinely has to do during an outage before recommending that anyone pay for a second link."},{"q":"Can calls go to mobiles?","a":"Yes, and it is often the simplest arrangement for a small site or an out-of-hours scenario. Calls can be sent to specific mobiles, to a group of them in an order you set, or to a queue that tries several people. Smartphone integration means those staff still present as the business rather than from a personal number, which keeps the arrangement invisible to your callers."},{"q":"How quickly does failover happen?","a":"We would rather describe the mechanism than quote you a number we cannot stand behind. Rerouting is a configuration change on our network, not work at your premises, so it does not depend on access to a building or on someone finding a cupboard. Some rules are set to apply automatically on a schedule or on failure to answer; others are invoked on request. What we agree during the design is which is which, who can ask, and how they ask, because that is what actually determines how long it takes on the day."},{"q":"How do we know it works?","a":"Because it has been tested with real calls, including the switch back, which is the part most plans leave out. We schedule the test at a time that suits your business and we are specifically looking for the gap between what the plan says and what a caller experiences. We then revisit it as sites, staffing and numbers change, alongside the quarterly review of your channels, so it does not quietly go out of date."}],
    relatedLinks: [{"href":"/services/sip-pri-trunking","label":"SIP & PRI Trunking","eyebrow":"Related","body":"The trunks and channels underneath the failover path, scoped by simultaneous calls rather than by desk."},{"href":"/services/hybrid-solutions","label":"Hybrid Solutions","eyebrow":"Related","body":"Bridging legacy equipment to the cloud, including the sites that are not ready to move yet."},{"href":"/technology","label":"Technology and Certified Endpoints","eyebrow":"Related","body":"Nightingale, the handsets we certify, and the technology partners our platform interoperates with."}],
    ctaHeading: "Find Out Where Your Calls Would Stop",
    ctaBody: "Tell us where your phone system lives and which sites have to keep answering. We will map the single points of failure and scope a failover path you can actually test.",
  },
]
